import sys
import os
import json
import itertools

from hex_utils import hex_distance, get_neighbors
from placement_rules import Tile, DistrictType, get_placement_rules, DISTRICT_NAME_MAP
from adjacency_rules import get_adjacency_calculator

def load_map(map_path):
    with open(map_path, "r") as f:
        data = json.load(f)
    tiles = {}
    for t in data["tiles"]:
        tile = Tile(x=t["x"], y=t["y"], terrain=t["terrain"], feature=t["feature"],
                    is_hills=t["is_hills"], is_floodplains=t.get("is_floodplains", False),
                    river_edges=t["river_edges"], resource=t["resource"], resource_type=None)
        if t["resource"]:
            res = t["resource"]
            if res in ("RESOURCE_IRON", "RESOURCE_HORSES", "RESOURCE_NITER", "RESOURCE_COAL", "RESOURCE_OIL", "RESOURCE_ALUMINUM", "RESOURCE_URANIUM"):
                tile.resource_type = "STRATEGIC"
            elif res in ("RESOURCE_WHEAT", "RESOURCE_RICE", "RESOURCE_MAIZE", "RESOURCE_DEER", "RESOURCE_SHEEP", "RESOURCE_COPPER", "RESOURCE_CRABS", "RESOURCE_FISH", "RESOURCE_BANANAS"):
                tile.resource_type = "BONUS"
            else:
                tile.resource_type = "LUXURY"
        if "MOUNTAIN" in t["terrain"]:
            tile.terrain = "MOUNTAIN"
        tiles[(t["x"], t["y"])] = tile
    return tiles

def solve():
    tiles = load_map("map_data.json")
    SPECIALTY_TYPES = [DistrictType.CAMPUS, DistrictType.HOLY_SITE, DistrictType.THEATER_SQUARE, 
                       DistrictType.COMMERCIAL_HUB, DistrictType.HARBOR, DistrictType.INDUSTRIAL_ZONE]
    INFRA_TYPES = [DistrictType.AQUEDUCT, DistrictType.DAM, DistrictType.CANAL]

    best_total = -1
    best_solution = None

    land_tiles = [coord for coord, tile in tiles.items() if not tile.is_water and not tile.is_mountain]
    interesting_tiles = []
    for coord in land_tiles:
        tile = tiles[coord]
        if tile.feature or tile.resource or tile.has_river:
            interesting_tiles.append(coord)
        else:
            for ncoord in get_neighbors(coord[0], coord[1]):
                ntile = tiles.get(ncoord)
                if ntile and (ntile.is_mountain or ntile.feature == "FEATURE_GEOTHERMAL_FISSURE" or ntile.feature == "FEATURE_REEF"):
                    interesting_tiles.append(coord)
                    break

    print(f"Searching {len(interesting_tiles)} potential city centers...")

    for cc_coord in interesting_tiles:
        rules = get_placement_rules(tiles, cc_coord, population=9)
        valid_tiles_by_type = {}
        for d_type in SPECIALTY_TYPES + INFRA_TYPES:
            v_tiles = []
            for dx in range(-3, 4):
                for dy in range(-3, 4):
                    target = (cc_coord[0] + dx, cc_coord[1] + dy)
                    if target == cc_coord: continue
                    if hex_distance(cc_coord[0], cc_coord[1], target[0], target[1]) <= 3:
                        res = rules.validate_placement(d_type, target[0], target[1], {})
                        if res.valid: v_tiles.append(target)
            if v_tiles: valid_tiles_by_type[d_type] = v_tiles

        for specialty_combo in itertools.combinations(SPECIALTY_TYPES, 3):
            base_types = list(specialty_combo)
            infra_to_add = [t for t in INFRA_TYPES if t in valid_tiles_by_type]

            # Try different orders or just all infra
            current_types = base_types + infra_to_add

            placed = {cc_coord: DistrictType.CITY_CENTER}
            # Greedy placement with a bit more care for IZ
            # Place Infra first as they often boost specialties
            order = [t for t in current_types if t in INFRA_TYPES] + [t for t in current_types if t not in INFRA_TYPES]

            for d_type in order:
                if d_type not in valid_tiles_by_type: continue
                best_t, best_t_total = None, -1
                for tile_coord in valid_tiles_by_type[d_type]:
                    if tile_coord in placed: continue
                    res = rules.validate_placement(d_type, tile_coord[0], tile_coord[1], placed)
                    if not res.valid: continue
                    placed[tile_coord] = d_type
                    calc = get_adjacency_calculator(tiles)
                    total, _ = calc.calculate_total_adjacency(placed)
                    if total > best_t_total:
                        best_t_total, best_t = total, tile_coord
                    del placed[tile_coord]
                if best_t: placed[best_t] = d_type

            calc = get_adjacency_calculator(tiles)
            total, per_district = calc.calculate_total_adjacency(placed)
            if total > best_total:
                best_total = total
                best_solution = {
                    "city_center": cc_coord,
                    "placements": {dtype.name: [coord[0], coord[1]] for coord, dtype in placed.items() if dtype != DistrictType.CITY_CENTER},
                    "adjacency_bonuses": {dist_key.split("@")[0]: res.total_bonus for dist_key, res in per_district.items()},
                    "total_adjacency": total
                }

    if best_solution:
        output = {
            "city_center": [best_solution["city_center"][0], best_solution["city_center"][1]],
            "placements": best_solution["placements"],
            "adjacency_bonuses": best_solution["adjacency_bonuses"],
            "total_adjacency": best_solution["total_adjacency"]
        }
        with open("solution.json", "w") as f:
            json.dump(output, f, indent=2)
        print(f"Best total found: {best_total}")

solve()

